// 위치/병원 선택값은 병원 Master를 단일 기준으로 사용한다.
// 기존 데이터와의 호환을 위해 병원 정보가 없을 때만 기본 위치를 사용한다.
function getLocations() {
  const hospitalNames = Array.isArray(state?.hospitals)
    ? sortHospitalMaster().map(h=>String(h?.name||'').trim()).filter(Boolean)
    : [];
  const locations = hospitalNames.length ? ['사무실', ...hospitalNames] : LOCATIONS;
  return [...new Set(locations)];
}
const TX_TYPES = ['입고','사용','선납','회수','조정(+)','조정(-)'];
const STORE_KEY = 'daekyung_tracking_modular_v10';
const LEGACY_STORE_KEYS = ['daekyung_tracking_modular_v1', 'DK_STATE'];
const LOCAL_SNAPSHOT_PREFIX = 'DK_STATE_SNAPSHOT_V12::';
const STATE_SCHEMA_VERSION = 10;

function today() { return new Date().toISOString().slice(0,10); }
function money(n) { return Number(n||0).toLocaleString('ko-KR'); }
function qty(n) { return Number(n||0).toLocaleString('ko-KR'); }
function byId(id) { return document.getElementById(id); }
function clone(x) { return JSON.parse(JSON.stringify(x)); }
function download(filename, text, type='text/plain;charset=utf-8') {
  if(String(type).includes('text/csv') && !String(text).startsWith('\uFEFF')) text='\uFEFF'+text;
  const blob = new Blob([text], {type}); const a=document.createElement('a');
  a.href=URL.createObjectURL(blob); a.download=filename; a.click(); URL.revokeObjectURL(a.href);
}
function toCSV(rows) { return rows.map(r=>r.map(v=>'"'+String(v ?? '').replaceAll('"','""')+'"').join(',')).join('\n'); }
function parseNumber(v) { const n=Number(String(v ?? '').replaceAll(',','').trim()); return isNaN(n)?0:n; }
function normalizeDate(v) {
  if(!v) return today();
  if(typeof v === 'number' && window.XLSX) { const d = XLSX.SSF.parse_date_code(v); return `${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`; }
  const s=String(v).trim().replace(/[.\/]/g,'-');
  const m=s.match(/(\d{4})-(\d{1,2})-(\d{1,2})/); if(m) return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;
  return s;
}
function initialState() {
  const products = DEFAULT_MASTER.map((p,i)=>({
    id:p.id || `P${String(i+1).padStart(3,'0')}`, category:p.category||'미분류', name:p.name,
    purchasePrice:0, salePrices:{'경북대':0,'영대':0,'동산':0,'기타':0}, stock:p.stock||{}
  }));
  DEFAULT_PRICES.forEach(pr=>{
    const p=products.find(x=>x.id===pr.id || x.name===pr.name);
    if(p) { p.purchasePrice=Number(pr.purchase||pr.purchasePrice||0); p.salePrices['기타']=Number(pr.sale||pr.salePrice||0); }
  });
  return {
    meta:{schemaVersion:STATE_SCHEMA_VERSION, createdAt:new Date().toISOString(), updatedAt:new Date().toISOString()},
    products, transactions:[], overuses:[], history:[], hospitals:[], audit:{system:[], physical:[], result:[], source:''}, settings:{}
  };
}
function migrateState(raw) {
  const base = initialState();
  const src = raw && typeof raw === 'object' ? raw : {};
  const next = Object.assign(base, src);
  next.meta = Object.assign({}, base.meta, src.meta || {}, {schemaVersion:STATE_SCHEMA_VERSION});
  next.products = Array.isArray(src.products) ? src.products : base.products;
  next.transactions = Array.isArray(src.transactions) ? src.transactions : [];
  next.overuses = Array.isArray(src.overuses) ? src.overuses : [];
  next.history = Array.isArray(src.history) ? src.history : [];
  next.hospitals = Array.isArray(src.hospitals) ? src.hospitals : [];
  next.audit = Object.assign({system:[], physical:[], result:[], source:''}, src.audit || {});
  next.settings = Object.assign({}, src.settings || {});
  return next;
}
function recoverMissingMasterData(current){
  const recovered=current;
  for(const key of LEGACY_STORE_KEYS){
    try{
      const raw=localStorage.getItem(key); if(!raw)continue;
      const legacy=migrateState(JSON.parse(raw));
      let changed=false;
      if(!recovered.hospitals?.length && legacy.hospitals?.length){recovered.hospitals=clone(legacy.hospitals);changed=true;}
      if(!recovered.hospitalPrices?.length && legacy.hospitalPrices?.length){recovered.hospitalPrices=clone(legacy.hospitalPrices);changed=true;}
      if(changed){
        const recoveredAt=new Date().toISOString();
        recovered.meta=Object.assign({},recovered.meta||{},{updatedAt:recoveredAt,cloudDirtyAt:recoveredAt,lastSaveReason:'legacy-master-recovery'});
      }
    }catch(e){}
  }
  return recovered;
}
function importantStateScore(value){
  if(!value||typeof value!=='object')return 0;
  const audit=value.audit||{};
  return (value.hospitals?.length||0)*20+(value.transactions?.length||0)*10+(value.hospitalPrices?.length||0)*3+(value.overuses?.length||0)*5+(value.history?.length||0)+(audit.system?.length||0)+(audit.physical?.length||0)+(audit.result?.length||0);
}
function mergeStateWithoutLoss(base,incoming){
  if(window.DKCloud?.safeMergeState)return migrateState(window.DKCloud.safeMergeState(base,incoming));
  return importantStateScore(incoming)>=importantStateScore(base)?migrateState(incoming):migrateState(base);
}
function recoverFromLocalSnapshots(current){
  if(current?.meta?.lastSaveReason==='reset')return current;
  let recovered=current;
  for(let slot=0;slot<10;slot++){
    try{
      const raw=localStorage.getItem(`${LOCAL_SNAPSHOT_PREFIX}${slot}`);if(!raw)continue;
      const snapshot=migrateState(JSON.parse(raw));
      if(importantStateScore(snapshot)>importantStateScore(recovered))recovered=mergeStateWithoutLoss(snapshot,recovered);
    }catch(e){}
  }
  if(importantStateScore(recovered)>importantStateScore(current)){
    const recoveredAt=new Date().toISOString();
    recovered.meta=Object.assign({},recovered.meta||{},{updatedAt:recoveredAt,cloudDirtyAt:recoveredAt,lastSaveReason:'local-snapshot-recovery'});
  }
  return recovered;
}
let state = loadState();
window.state = state;
function loadState() {
  const keys = [STORE_KEY, ...LEGACY_STORE_KEYS];
  for(const key of keys) {
    try {
      const raw = localStorage.getItem(key);
      if(raw) {
        const loaded = recoverFromLocalSnapshots(recoverMissingMasterData(migrateState(JSON.parse(raw))));
        if(key !== STORE_KEY) localStorage.setItem(STORE_KEY, JSON.stringify(loaded));
        return loaded;
      }
    } catch(e) {}
  }
  return initialState();
}
function saveState(reason='auto') {
  try {
    const previous=localStorage.getItem(STORE_KEY);
    if(previous && reason!=='reset'){
      try{
        const previousState=JSON.parse(previous);
        if(importantStateScore(previousState)>0){const slot=Math.floor(Date.now()/60000)%10;localStorage.setItem(`${LOCAL_SNAPSHOT_PREFIX}${slot}`,previous);}
      }catch(e){}
    }
    const savedAt=new Date().toISOString();
    state.meta = Object.assign({}, state.meta || {}, {schemaVersion:STATE_SCHEMA_VERSION, updatedAt:savedAt, lastSaveReason:reason, cloudDirtyAt:savedAt});
    localStorage.setItem(STORE_KEY, JSON.stringify(state));
    window.state = state;
    if(window.DKCloud) window.DKCloud.queuePush(state, reason);
    showAutosaveStatus();
    return true;
  } catch(e) {
    console.error('저장 실패', e);
    alert('브라우저 저장공간이 부족하거나 저장에 실패했습니다. JSON 백업 후 불필요한 데이터를 정리해 주세요.');
    return false;
  }
}
function addHistory(type, content, count=1) { state.history.unshift({time:new Date().toLocaleString('ko-KR'), type, content, count}); state.history=state.history.slice(0,300); saveState('history'); }
function resetAll() { if(confirm('전체 데이터를 초기화할까요?')) { state=initialState(); saveState('reset'); clearCurrentPageDraft(); location.reload(); } }
function exportBackup() { download(`daekyung_backup_v11_${today()}.json`, JSON.stringify(state,null,2), 'application/json;charset=utf-8'); }
function restoreBackup(evt) { const f=evt.target.files[0]; if(!f) return; const r=new FileReader(); r.onload=()=>{ try{state=migrateState(JSON.parse(r.result)); saveState('restore'); location.reload();}catch(e){alert('JSON 파일을 확인하세요.')} }; r.readAsText(f); }
function pageDraftKey(){ return 'DK_FORM_DRAFT_V10::' + location.pathname.split('/').pop(); }
function rememberLastPage(){ try{ localStorage.setItem('DK_LAST_PAGE_V10', location.pathname.split('/').pop() || 'index.html'); }catch(e){} }
function getLastPage(){ try{return localStorage.getItem('DK_LAST_PAGE_V10') || 'index.html';}catch(e){return 'index.html';} }
function saveCurrentPageDraft(){
  const draft = {};
  document.querySelectorAll('input, select, textarea').forEach(el=>{
    if(!el.id || el.type === 'file' || el.type === 'button' || el.type === 'submit') return;
    draft[el.id] = (el.type === 'checkbox') ? el.checked : el.value;
  });
  try{ localStorage.setItem(pageDraftKey(), JSON.stringify(draft)); }catch(e){}
}
function restoreCurrentPageDraft(){
  let draft={};
  try{ draft = JSON.parse(localStorage.getItem(pageDraftKey()) || '{}'); }catch(e){}
  Object.entries(draft).forEach(([id,val])=>{ const el=byId(id); if(!el || el.type === 'file') return; if(el.type === 'checkbox') el.checked=!!val; else el.value=val; });
}
function clearCurrentPageDraft(){ try{ localStorage.removeItem(pageDraftKey()); }catch(e){} }
function setupAutoDraft(){
  restoreCurrentPageDraft();
  document.addEventListener('input', e=>{ if(e.target && e.target.matches('input,select,textarea')) saveCurrentPageDraft(); }, true);
  document.addEventListener('change', e=>{ if(e.target && e.target.matches('input,select,textarea')) saveCurrentPageDraft(); }, true);
}
function showAutosaveStatus(){
  const el=byId('autosaveStatus');
  if(el) el.textContent = '자동저장 ' + new Date().toLocaleTimeString('ko-KR', {hour:'2-digit', minute:'2-digit'});
}
window.addEventListener('beforeunload',saveCurrentPageDraft);
function productByName(name) { return state.products.find(p=>p.name===name); }
function productById(id) { return state.products.find(p=>p.id===id); }
function productOptions(select, includeAll=false) { if(!select) return; select.innerHTML=(includeAll?'<option value="">전체</option>':'')+state.products.map(p=>`<option value="${p.id}">${p.name}</option>`).join(''); }
function categoryOptions(select, includeAll=true) { if(!select) return; const cats=[...new Set(state.products.map(p=>p.category||'미분류'))].sort(); select.innerHTML=(includeAll?'<option value="">전체</option>':'')+cats.map(c=>`<option value="${c}">${c}</option>`).join(''); }
function locationOptions(select, includeAll=false) { if(!select) return; select.innerHTML=(includeAll?'<option value="">전체</option>':'')+getLocations().map(l=>`<option value="${l}">${l}</option>`).join(''); }
function refillOptions(select,fill,includeAll=false){
  if(!select)return;
  const selected=select.value;
  fill(select,includeAll);
  if([...select.options].some(o=>o.value===selected))select.value=selected;
}

function refreshCurrentPageFromState(){
  refillOptions(byId('mLoc'),locationOptions);
  refillOptions(byId('oLoc'),locationOptions);
  refillOptions(byId('invLoc'),locationOptions);
  refillOptions(byId('mProd'),productOptions);
  refillOptions(byId('oProd'),productOptions);
  refillOptions(byId('hpHospital'),hospitalOptions,true);
  refillOptions(byId('priceHospital'),hospitalOptions,true);
  refillOptions(byId('masterCat'),categoryOptions,true);
  refillOptions(byId('priceCat'),categoryOptions,true);
  if(typeof auditData!=='undefined')auditData=state.audit||{system:[],physical:[],result:[],source:''};
  ['renderDashboard','renderInventory','renderTx','renderMaster','renderHospital','renderHospitalPrice','renderPrice','renderReport','renderAudit']
    .forEach(name=>{if(typeof window[name]==='function')window[name]();});
}
window.addEventListener('dk-state-updated',refreshCurrentPageFromState);
function stockCell(p, loc) { return p.stock?.[loc] || {stock:0,current:0,in:0,use:0,prepaid:0,base:0}; }
function transactionEffectForLocation(t, loc) {
  const q = Number(t.qty || 0);
  const txLoc = t.location || '';
  const type = t.type || '';

  // 선납: 사무실 재고가 병원으로 이동한 것으로 처리
  // - 거래 위치가 병원이면 병원 현재고 증가
  // - 사무실 현재고는 같은 수량만큼 감소
  if(type === '선납') {
    if(loc === '사무실') return -q;
    if(txLoc === loc) return q;
    return 0;
  }

  // 회수: 병원 재고가 사무실로 돌아온 것으로 처리
  // - 거래 위치가 병원이면 병원 현재고 감소
  // - 사무실 현재고는 같은 수량만큼 증가
  if(type === '회수') {
    if(loc === '사무실') return q;
    if(txLoc === loc) return -q;
    return 0;
  }

  // 일반 거래: 해당 위치의 현재고를 직접 증감
  if(txLoc !== loc) return 0;
  if(['입고','조정(+)'].includes(type)) return q;
  if(['사용','조정(-)','과사용'].includes(type)) return -q;
  return 0;
}

function currentQty(p, loc='') {
  const locs = loc ? [loc] : getLocations();
  return locs.reduce((sum, l) => {
    const base = Number(stockCell(p, l).stock || 0);
    const tx = state.transactions
      .filter(t => t.productId === p.id)
      .reduce((a, t) => a + transactionEffectForLocation(t, l), 0);
    return sum + base + tx;
  }, 0);
}

function inventorySummary() {
  let totalStock = 0, totalCurrent = 0, totalUse = 0, totalOver = 0, loc = {};
  getLocations().forEach(l => loc[l] = {stock:0,current:0,in:0,use:0,prepaid:0,recovery:0});

  state.products.forEach(p => getLocations().forEach(l => {
    const c = stockCell(p, l);
    loc[l].stock += Number(c.stock || 0);
    const cur = currentQty(p, l);
    loc[l].current += cur;
    totalStock += Number(c.stock || 0);
    totalCurrent += cur;
  }));

  state.transactions.forEach(t => {
    const q = Number(t.qty || 0);
    if(t.type === '입고' && loc[t.location]) loc[t.location].in += q;
    if(t.type === '사용' && loc[t.location]) {
      loc[t.location].use += q;
      totalUse += q;
    }
    if(t.type === '선납') {
      if(loc[t.location]) loc[t.location].prepaid += q;
    }
    if(t.type === '회수') {
      if(loc[t.location]) loc[t.location].recovery += q;
    }
  });

  totalOver = state.overuses.filter(o => o.status !== '정리완료').reduce((a,o) => a + Number(o.qty || 0), 0);
  return {totalStock,totalCurrent,totalUse,totalOver,loc};
}
function salePrice(p, hospital) { return Number((p.salePrices||{})[hospital] || (p.salePrices||{})['기타'] || 0); }
function purchasePrice(p) { return Number(p.purchasePrice||0); }
function readWorkbook(file, cb) { const reader=new FileReader(); reader.onload=e=>{ try{const wb=XLSX.read(new Uint8Array(e.target.result),{type:'array'}); const ws=wb.Sheets[wb.SheetNames[0]]; cb(XLSX.utils.sheet_to_json(ws,{defval:''}));}catch(error){console.error('Excel read failed',error);alert('엑셀 파일을 읽지 못했습니다. 업로드 샘플 양식인지 확인하세요.');} }; reader.onerror=()=>alert('엑셀 파일을 읽지 못했습니다.'); reader.readAsArrayBuffer(file); }
function updateNav() { const page=location.pathname.split('/').pop()||'index.html'; document.querySelectorAll('.page-link').forEach(a=>{ if(a.getAttribute('href')===page) a.classList.add('active'); }); }
async function commonInit() {
  updateNav();
  rememberLastPage();
  const rf=byId('restoreFile'); if(rf) rf.onchange=restoreBackup;
  installCloudControls();
  if(window.DKCloud){
    try{
      const boot=await DKCloud.bootstrap();
      if(boot?.remote?.state_data){
        const mainRemoteState=migrateState(boot.remote.state_data);
        const localHasPendingChanges=!!state.meta?.cloudDirtyAt;
        let protectedCloudState=null;
        const backups=Array.isArray(boot.remote.backup_states)?[...boot.remote.backup_states].reverse():[];
        backups.forEach(row=>{if(row?.state_data)protectedCloudState=protectedCloudState?mergeStateWithoutLoss(protectedCloudState,migrateState(row.state_data)):migrateState(row.state_data);});
        protectedCloudState=protectedCloudState?mergeStateWithoutLoss(protectedCloudState,mainRemoteState):mainRemoteState;
        let finalState=protectedCloudState;
        if(localHasPendingChanges||importantStateScore(state)>0)finalState=mergeStateWithoutLoss(protectedCloudState,state);
        const recoveredData=importantStateScore(finalState)>importantStateScore(mainRemoteState);
        const syncAt=new Date().toISOString();
        finalState.meta=Object.assign({},finalState.meta||{},{lastCloudSyncAt:boot.remote.updated_at||syncAt,cloudDirtyAt:(recoveredData||localHasPendingChanges)?syncAt:''});
        state=finalState;
        window.state=state;
        localStorage.setItem(STORE_KEY,JSON.stringify(state));
        window.dispatchEvent(new CustomEvent('dk-state-updated',{detail:{source:recoveredData?'cloud-snapshot-recovery':'cloud'}}));
        if(recoveredData||localHasPendingChanges){
          DKCloud.queuePush(state,recoveredData?'bootstrap-snapshot-recovery':'bootstrap-pending-local');
        }
      } else if(boot?.mode==='cloud') DKCloud.queuePush(state,'bootstrap-first-upload');
    }catch(e){ console.error(e); }
  }
}
function installCloudControls(){
  const top=document.querySelector('.top');
  const actions=document.querySelector('.top .actions');
  if(!top || !actions) return;

  // v11.1 공통 헤더: 페이지 정보 / 로그인 정보 / 도구 모음의 3개 역할을 분리합니다.
  const pageInfo=top.firstElementChild;
  if(pageInfo) pageInfo.classList.add('top-page-info');
  top.classList.add('app-header');
  actions.classList.add('top-tools');

  let userArea=top.querySelector('.top-user-area');
  if(!userArea){
    userArea=document.createElement('div');
    userArea.className='top-user-area';
    top.insertBefore(userArea, actions);
  }

  let st=byId('cloudStatus');
  if(!st){
    st=document.createElement('span');
    st.id='cloudStatus';
    st.className='cloud-status';
    st.textContent='☁ Cloud 확인';
  }
  let user=byId('cloudUser');
  if(!user){
    user=document.createElement('span');
    user.id='cloudUser';
    user.className='cloud-user';
  }
  let out=byId('cloudLogout');
  if(!out){
    out=document.createElement('button');
    out.id='cloudLogout';
    out.className='btn header-logout';
    out.textContent='로그아웃';
    out.onclick=()=>window.DKCloud?.signOut();
  }
  userArea.append(st,user,out);

  // 자동저장 상태는 작업 도구 오른쪽 끝에 고정합니다.
  const autosave=byId('autosaveStatus');
  if(autosave) actions.appendChild(autosave);

  const paint=(d)=>{
    const st=byId('cloudStatus'), user=byId('cloudUser');
    if(!st)return;
    st.className='cloud-status';
    if(!d.configured){st.textContent='☁ Local 모드';}
    else if(!d.online){st.textContent='☁ 오프라인 · 로컬저장';st.classList.add('offline');}
    else if(d.lastError){st.textContent='☁ 동기화 오류';st.classList.add('error');}
    else if(d.syncing){st.textContent='☁ 동기화 중';st.classList.add('syncing');}
    else {st.textContent='☁ Cloud 연결';}
    if(user){
      user.textContent=d.email||'';
      user.title=d.email||'';
    }
  };
  window.addEventListener('dk-cloud-status',e=>paint(e.detail));
  if(window.DKCloud) paint(DKCloud.status);
}
document.addEventListener('DOMContentLoaded', commonInit);
window.addEventListener('dk-cloud-push-success',e=>{
  try{
    if(e.detail?.stateData)state=migrateState(e.detail.stateData);
    state.meta=Object.assign({},state.meta||{},{cloudDirtyAt:'',lastCloudSyncAt:e.detail?.updatedAt||new Date().toISOString()});
    window.state=state;
    localStorage.setItem(STORE_KEY,JSON.stringify(state));
    window.dispatchEvent(new CustomEvent('dk-state-updated',{detail:{source:'cloud-save-confirmed'}}));
  }catch(error){console.error('Cloud sync marker failed',error);}
});

function compareHospitalCode(a,b){
  const aCode=String(a?.code||'').trim(),bCode=String(b?.code||'').trim();
  if(!aCode&&bCode)return 1;if(aCode&&!bCode)return -1;
  const codeOrder=aCode.localeCompare(bCode,'ko',{numeric:true,sensitivity:'base'});
  return codeOrder||String(a?.name||'').localeCompare(String(b?.name||''),'ko',{numeric:true,sensitivity:'base'});
}
function sortHospitalMaster(){if(!Array.isArray(state.hospitals))state.hospitals=[];state.hospitals.sort(compareHospitalCode);return state.hospitals;}
function ensureHospitalState(){ if(!state.hospitals||!Array.isArray(state.hospitals)){state.hospitals=HOSPITALS.map((name,i)=>({code:`H${String(i+1).padStart(3,'0')}`,name,manager:'',phone:'',address:'',memo:''}));} sortHospitalMaster(); if(!state.lots||!Array.isArray(state.lots)){state.lots=[];} }
function hospitalOptions(select,includeAll=false){ensureHospitalState(); if(!select)return; select.innerHTML=(includeAll?'<option value="">전체</option>':'')+sortHospitalMaster().map(h=>`<option value="${h.name}">${h.name}</option>`).join('');}
function erpInit(){ensureHospitalState();}
document.addEventListener('DOMContentLoaded',erpInit);

/* ===== v6 Hospital Price Extension ===== */
function ensureV6State(){
  if(!state.hospitals || !Array.isArray(state.hospitals)){
    state.hospitals = HOSPITALS.map((name, idx)=>({
      code:`H${String(idx+1).padStart(3,'0')}`,
      name, manager:'', phone:'', address:'', memo:''
    }));
  }
  if(!state.hospitalPrices || !Array.isArray(state.hospitalPrices)){
    state.hospitalPrices = [];
  }
  // migrate legacy product salePrices to hospitalPrices
  state.products.forEach(p=>{
    p.defaultSalePrice = Number(p.defaultSalePrice || p.salePrice || p.salePrices?.['기타'] || 0);
    if(p.salePrices){
      Object.entries(p.salePrices).forEach(([hospital, price])=>{
        if(price === undefined || price === null || Number(price) === 0) return;
        const exists = state.hospitalPrices.find(x=>x.productId===p.id && x.hospitalName===hospital);
        if(!exists) state.hospitalPrices.push({hospitalName:hospital, productId:p.id, salePrice:Number(price||0)});
      });
      // Keep legacy object only for backward compatibility, but v6 UI no longer writes it.
    }
  });
}
function getHospitalList(){
  ensureV6State();
  return sortHospitalMaster();
}
function hospitalOptions(select, includeAll=false){
  ensureV6State();
  if(!select) return;
  select.innerHTML=(includeAll?'<option value="">전체</option>':'')+sortHospitalMaster().map(h=>`<option value="${h.name}">${h.name}</option>`).join('');
}
function getHospitalPrice(productId, hospitalName){
  ensureV6State();
  const row = state.hospitalPrices.find(x=>x.productId===productId && x.hospitalName===hospitalName);
  if(row) return Number(row.salePrice||0);
  const p = productById(productId);
  return Number(p?.defaultSalePrice || p?.salePrice || p?.salePrices?.['기타'] || 0);
}
function setHospitalPrice(productId, hospitalName, salePrice){
  ensureV6State();
  let row = state.hospitalPrices.find(x=>x.productId===productId && x.hospitalName===hospitalName);
  if(!row){
    row = {productId, hospitalName, salePrice:0};
    state.hospitalPrices.push(row);
  }
  row.salePrice = Number(salePrice || 0);
}
function salePrice(p, hospital){
  if(!p) return 0;
  return getHospitalPrice(p.id, hospital || '기타');
}
function defaultSalePrice(p){
  return Number(p?.defaultSalePrice || p?.salePrice || p?.salePrices?.['기타'] || 0);
}
document.addEventListener('DOMContentLoaded',()=>{ ensureV6State(); setupAutoDraft(); rememberLastPage(); });
